	isTrue(t, isNaN32(rs.Unwrap(ParseF32("-NaN"))))

	isTrue(t, math.IsNaN(rs.Unwrap(ParseF64("NaN"))))
	isTrue(t, math.IsNaN(rs.Unwrap(ParseF64("-NaN"))))
